   345→    {
   346→        ulong v = transaction.Signature!.V;
   347→        return releaseSpec.IsEip155Enabled && (v == chainId * 2 + 35ul || v == chainId * 2 + 36ul)
   348→            ? ValidationResult.Success
   349→            : base.ValidateChainId(transaction, releaseSpec);
   350→    }
   351→}
   352→
   353→public sealed class SignatureTxValidator : BaseSignatureTxValidator
   354→{
   355→    public static readonly SignatureTxValidator Instance = new();
   356→    private SignatureTxValidator() { }
   357→}
